"Орден Оберега · записано Велимиром и Ловчими всех земель":"ताबीज़ संघ · वेलिमीर और हर देश के शिकारियों द्वारा लिखा गया",
"Орден Оберега":"ताबीज़ संघ",
"Ловчие Ордена берегут границу между Явью и Навью. Старший Ловчий — <b>Велимир</b>: он встречает каждого новичка и ведёт Летопись. Клятва Ордена проста: <b>беречь духов, беречь границу, беречь друг друга</b>.":"संघ के शिकारी याव् और नाव् के बीच की सीमा की रक्षा करते हैं। वरिष्ठ शिकारी हैं <b>वेलिमीर</b>: वे हर नए शिकारी का स्वागत करते हैं और गाथा लिखते हैं। संघ की शपथ सरल है: <b>आत्माओं की रक्षा, सीमा की रक्षा, एक-दूसरे की रक्षा</b>।",
"Кощей Бессмертный":"अमर कोश्चेई",
"Царь Нави. Это он истончил границу в Тонкую ночь. О том, чем всё закончилось, рассказывает вторая книга Летописи.":"नाव् का राजा। पतली रात में सीमा को उसी ने पतला किया था। आगे क्या हुआ, यह गाथा की दूसरी किताब बताती है।",
"Новые духи":"नई आत्माएँ",
"Город рождает своих духов: из Wi‑Fi, фонарей, трамваев и пакетов. В старых книгах о таких не писали — пишем мы.":"शहर अपनी आत्माएँ ख़ुद जन्म देता है: Wi‑Fi, लैंपपोस्ट, ट्राम और पॉलीथीन से। पुरानी किताबों में इनके बारे में कुछ नहीं लिखा — अब हम लिख रहे हैं।",
"и":"और",
"Сильнее против: {0}. Приёмы: «{1}», «{2}».":"इनके ख़िलाफ़ ताक़तवर: {0}। दाँव: “{1}”, “{2}”।",
"В бестиарии Ордена — <b>{0} видов</b> духов. У каждого своя стихия, редкость и семейство: малыши превращаются во взрослых духов.":"संघ के आत्मा-कोश में आत्माओं की <b>{0} प्रजातियाँ</b> हैं। हर एक का अपना तत्व, दुर्लभता और परिवार है: छोटी आत्माएँ बड़ी होकर विकसित होती हैं।",
"Шесть стихий":"छह तत्व",
"Ночью чаще встречаются духи Тени и Ветра, у каждого района города — своя любимая стихия. Есть и особые духи: ночные, дневные, сезонные, региональные и духи родных земель.":"रात में छाया और पवन की आत्माएँ ज़्यादा मिलती हैं, और शहर के हर इलाक़े का अपना पसंदीदा तत्व है। ख़ास आत्माएँ भी हैं: रात की, दिन की, मौसमी, क्षेत्रीय और जन्मभूमि की आत्माएँ।",
"Поймать можно каждого. Духов чужих краёв и не своего сезона — «гостей издалека» — приводят трудные поручения родников (★★★), их продают на Аукционе и дарят друзья. Легенды ждут в великих разломах и в финалах книг Летописи.":"हर आत्मा पकड़ी जा सकती है। दूसरे इलाक़ों और दूसरे मौसम की आत्माएँ — “दूर के मेहमान” — झरनों के कठिन मिशन (★★★) लाते हैं, वे नीलामी में बिकती हैं और दोस्त तोहफ़े में देते हैं। लेजेंडरी आत्माएँ महान दरारों में और गाथा की किताबों के अंत में इंतज़ार करती हैं।",
"Сияющие":"चमकीली",
"Редкие цветовые варианты — примерно 1 из {0}. Их выдают искры вокруг духа.":"दुर्लभ रंग-रूप — लगभग {0} में 1। आत्मा के चारों ओर चिंगारियाँ इन्हें पहचानने में मदद करती हैं।",
"Бросок":"फेंकना",
"Коснись духа на карте, затем смахни оберег вверх. Сила свайпа — дальность броска.":"नक्शे पर आत्मा को छुओ, फिर ताबीज़ को ऊपर स्वाइप करो। स्वाइप की ताक़त — फेंकने की दूरी।",
"Кольцо":"घेरा",
"Внутреннее кольцо сжимается. Попади, пока оно маленькое, — будет «Отлично!» или «Превосходно!»: больше опыта и выше шанс.":"अंदर का घेरा सिकुड़ता है। जब वह छोटा हो तब निशाना लगाओ — “बढ़िया!” या “शानदार!” मिलेगा: ज़्यादा XP और ज़्यादा मौक़ा।",
"Мёд":"शहद",
