"Писать в Чат Ордена можно с {0} уровня. С {1} уровня открыт Аукцион: продавай духов за искры или златники, лот живёт {2} часа.":"संघ चैट में लेवल {0} से लिख सकते हो। लेवल {1} से नीलामी खुलती है: आत्माओं को चिंगारियों या ज़्लातनिक में बेचो, लॉट {2} घंटे चलता है।",
"При выставлении берётся залог — {0}% от цены: если духа купят, он вернётся вместе с выручкой, если нет — пропадёт. Подсказка покажет, за сколько таких духов продавали недавно. Кнопка «Не выше моего уровня» прячет духов, которые у тебя урежутся до твоего уровня.":"लॉट लगाते समय ज़मानत ली जाती है — कीमत की {0}%: आत्मा बिकी तो कमाई के साथ लौटेगी, नहीं तो चली जाएगी। संकेत बताएगा कि ऐसी आत्माएँ हाल में कितने में बिकीं। “मेरे लेवल तक” बटन उन आत्माओं को छिपाता है जो तुम्हारे पास तुम्हारे लेवल तक घट जाएँगी।",
"Летопись — сюжет Ордена: главы с заданиями, наградами и легендарными духами в конце каждой книги. Открывается во вкладке «Задания».":"गाथा — संघ की कहानी: क्वेस्ट और इनाम वाले अध्याय, और हर किताब के अंत में लेजेंडरी आत्माएँ। “क्वेस्ट” टैब में खुलती है।",
"Главы идут через весь путь Ловчего — до {0} уровня: каждая открывается на своём уровне (он указан у главы). Под каждым шагом — подсказка, куда идти и что делать, а кнопка «Показать» открывает нужный раздел.":"अध्याय शिकारी की पूरी राह में चलते हैं — लेवल {0} तक: हर अध्याय अपने लेवल पर खुलता है (अध्याय पर लिखा है)। हर क़दम के नीचे संकेत है कि कहाँ जाना है और क्या करना है, और “दिखाओ” बटन सही हिस्सा खोलता है।",
