"Покров":"पोक्रोव",
"Первые туманы и иней: духи Ветра и Воды встречаются чаще, Листопадница — повсюду, в родниках больше добычи.":"पहले कोहरे और पाला: पवन और जल की आत्माएँ ज़्यादा मिलती हैं, लिस्तोपाद्नित्सा — हर जगह, झरनों में ज़्यादा माल।",
"Велесова ночь":"वेलेस की रात",
"Граница миров тоньше всего: духи Тени втрое чаще, в великих разломах ждёт Кощей, сияющие Тени вдвое чаще.":"दुनियाओं की सीमा सबसे पतली: छाया की आत्माएँ तिगुनी, महान दरारों में कोश्चेई इंतज़ार करता है, चमकीली छाया-आत्माएँ दोगुनी।",
"Этот родник теперь принадлежит Нави!":"यह झरना अब नाव् का है!",
"Твои духи будут служить Кощею!":"तुम्हारी आत्माएँ कोश्चेई की सेवा करेंगी!",
"Орден Оберега? Никогда о таком не слышал.":"ताबीज़ संघ? कभी नाम भी नहीं सुना।",
"Граница рухнет, и мы заберём весь город!":"सीमा टूटेगी, और पूरा शहर हमारा होगा!",
"Думаешь, оберегом меня остановишь?":"सोचते हो, ताबीज़ से मुझे रोक लोगे?",
