"Шапка с рунами и посох с огоньком: мудрость старых волхвов.":"रूनों वाली टोपी और लौ वाली लाठी: पुराने वोल्ख़्वों की बुद्धि।",
"Богатырь":"बोगातिर",
"Шелом, кольчуга и алое корзно — хоть сейчас на заставу.":"टोप, ज़िरह-बख़्तर और लाल लबादा — अभी सरहद पर जाने को तैयार।",
"Вороний":"कौआ",
"Маска-клюв и плащ из чёрных перьев. Вороны Нави шепчут тебе вести.":"चोंच वाला मुखौटा और काले पंखों का लबादा। नाव् के कौए तुम्हारे कान में ख़बरें फुसफुसाते हैं।",
"Навий страж":"नाव् का प्रहरी",
"Рогатая личина и пламя Нави. Духи расступаются перед тобой.":"सींगों वाला मुखौटा और नाव् की लपटें। आत्माएँ तुम्हारे आगे रास्ता छोड़ देती हैं।",
"Жар-перо":"अग्नि-पंख",
"Убор из огненных перьев Жар-птицы. Светится даже в самую тёмную ночь.":"ज़ार-प्तित्सा के आग के पंखों का ताज। सबसे अँधेरी रात में भी चमकता है।",
"Княжий":"राजसी",
"Княжья шапка с соболем и самоцветами — наряд первых Ловчих Ордена.":"सेबल-फ़र और रत्नों वाली राजसी टोपी — संघ के पहले शिकारियों की पोशाक।",
"Ночь":"रात",
"Сумерки":"गोधूलि",
