"Вторжение Нави":"नाव् का आक्रमण",
"Родник «{0}»":"झरना “{0}”",
"Захвачен Навью":"नाव् के क़ब्ज़े में",
"СИЛА ОТРЯДА":"दस्ते की शक्ति",
"выбрать духа":"आत्मा चुनो",
"Омрачённые духи":"अंधकारमय आत्माएँ",
"слабость":"कमज़ोरी",
"силы на твоей стороне":"ताक़त तुम्हारी तरफ़ है",
"отряд сильнее — бей в слабость":"दस्ता ज़्यादा ताक़तवर — कमज़ोरी पर वार करो",
"сила {0}":"शक्ति {0}",
"Победа освободит родник и позволит спасти одного из омрачённых духов.":"जीत झरने को आज़ाद करेगी और एक अंधकारमय आत्मा को बचाने देगी।",
"Вторжений отбито":"आक्रमण रोके",
"В команде дух без сил":"टीम में बेहोश आत्मा है",
"Сразиться":"लड़ो",
"Нужна команда":"टीम चाहिए",
"Дружеский поединок":"दोस्ताना द्वंद्व",
"Сильнейшие духи друга":"दोस्त की सबसे ताक़तवर आत्माएँ",
"Награда за сегодня уже получена — сейчас это тренировка (+100 опыта за победу).":"आज का इनाम मिल चुका है — अब यह अभ्यास है (जीत पर +100 XP)।",
"Награда за первую победу за день: 800 опыта, ✦ 500, обереги и мёд, +1 ★ дружбы.":"दिन की पहली जीत का इनाम: 800 XP, ✦ 500, ताबीज़ और शहद, दोस्ती के +1 ★।",
"Поединок с другом":"दोस्त से द्वंद्व",
"Смена":"बदलो",
"Приём":"दाँव",
"Тапай — быстрая атака, она копит энергию.<br>Полная шкала — жми «Приём». Щиты берегут от приёмов хранителя.":"टैप करो — तेज़ हमला, इससे ऊर्जा भरती है।<br>पूरा मीटर — “दाँव” दबाओ। ढालें रखवाले के दाँवों से बचाती हैं।",
"Бой!":"लड़ाई!",
"Мало энергии — атакуй тапами":"ऊर्जा कम है — टैप से हमला करो",
"Тапай!":"टैप करो!",
"Щит!":"ढाल!",
"Щит ({0})":"ढाल ({0})",
"Принять удар":"वार झेलो",
"{0} призывает: {1}":"{0} बुलाता है: {1}",
"Смена будет доступна через {0} с":"{0} सेकंड बाद बदल सकोगे",
"Некого выпустить":"भेजने को कोई नहीं",
"Дух без сил! Кого выпустить?":"आत्मा बेहोश! किसे भेजें?",
"Сменить духа":"आत्मा बदलो",
"Победа не засчитана":"जीत दर्ज नहीं हुई",
"Сервер не подтвердил этот бой. Проверь интернет и попробуй снова.":"सर्वर ने इस लड़ाई की पुष्टि नहीं की। इंटरनेट जाँचो और फिर कोशिश करो।",
"На карту":"नक्शे पर",
"Защитники «{0}» отступили — Капище «{1}» свободно!":"“{0}” के रक्षक पीछे हट गए — कापिश्चे “{1}” आज़ाद है!",
"Победа засчитана, но пока шёл бой, на Капище сменились защитники.":"जीत दर्ज हुई, पर लड़ाई के दौरान कापिश्चे पर रक्षक बदल गए।",
"«Достойно, Ловчий», — {0} склоняет голову. Капище «{1}» освящено тобой до конца дня.":"“शाबाश, शिकारी,” — {0} सिर झुकाता है। कापिश्चे “{1}” दिन के अंत तक तुम्हारे द्वारा पवित्र है।",
"Победа!":"जीत!",
"Поставь своего защитника — и Капище перейдёт твоей дружине.":"अपना रक्षक रखो — और कापिश्चे तुम्हारे दल का हो जाएगा।",
"Поражение":"हार",
"«Приходи, когда окрепнешь», — говорит {0}. Попробуй другую команду: смотри на стихии хранителя и береги щиты для его приёмов.":"“ताक़तवर होकर आना,” — {0} कहता है। दूसरी टीम आज़माओ: रखवाले के तत्व देखो और उसके दाँवों के लिए ढालें बचाकर रखो।",
"Хорошая тренировка! Награда за поединок с {0} сегодня уже получена.":"अच्छा अभ्यास! {0} से द्वंद्व का आज का इनाम मिल चुका है।",
"{0} жмёт тебе руку: «Честный бой!» Дружба крепнет.":"{0} तुमसे हाथ मिलाता है: “ईमानदार लड़ाई!” दोस्ती मज़बूत होती है।",
"<b>+1 ★</b> дружбы":"दोस्ती के <b>+1 ★</b>",
"Духи {0} оказались сильнее. Подбери команду против их стихий и попробуй снова — поединки с другом не ограничены.":"{0} की आत्माएँ ज़्यादा ताक़तवर निकलीं। उनके तत्वों के ख़िलाफ़ टीम चुनो और फिर कोशिश करो — दोस्त से द्वंद्व की कोई सीमा नहीं।",
"Родник освобождён!":"झरना आज़ाद हुआ!",
