"Игре нужна геопозиция, чтобы показать духов, родники и разломы вокруг. Прогресс хранится на сервере игры и доступен только тебе; сервер проверяет каждое действие (поэтому нужен интернет), в прогрессе есть дневник с местами поимок. Для проверки действий на карте сервер получает твоё местоположение. Чтобы загрузить места на карте и погоду, район (~1 км) запрашивается у OpenStreetMap и Open-Meteo (погоду можно выключить в настройках). Точные координаты уходят на сервер, только если ты сам предложишь новое место.":"आसपास की आत्माएँ, झरने और दरारें दिखाने के लिए गेम को लोकेशन चाहिए। प्रोग्रेस गेम सर्वर पर रहती है और सिर्फ़ तुम देख सकते हो; सर्वर हर क़दम की जाँच करता है (इसलिए इंटरनेट चाहिए), प्रोग्रेस में पकड़ने की जगहों वाली डायरी होती है। नक्शे पर क़दमों की जाँच के लिए सर्वर तुम्हारी लोकेशन लेता है। नक्शे की जगहें और मौसम लोड करने के लिए इलाक़ा (~1 किमी) OpenStreetMap और Open-Meteo से माँगा जाता है (मौसम सेटिंग्स में बंद कर सकते हो)। सटीक निर्देशांक सर्वर पर तभी जाते हैं, जब तुम ख़ुद कोई नई जगह सुझाओ।",
"Разрешить геопозицию":"लोकेशन की अनुमति दो",
"Уже играешь?":"पहले से खेल रहे हो?",
